function studentForm(s={}){const parents=db.parents.map(p=>{const u=db.users.find(x=>x.id===p.userId);return {...p,name:u?.name||'',email:u?.email||''}});const linked=parents.find(p=>p.id===s.parentId)||{};return head(s.id?'Edit Student':'Add Student','Student details, student ID login and parent linking')+card(`<form method="post" action="${s.id?'/students/'+s.id:'/students'}" class="formgrid"><label>Full name<input name="name" value="${esc(s.name||'')}" required></label><label>Student ID<input name="studentId" value="${esc(s.studentId||'')}" placeholder="STU007" required></label><label>Admission No.<input name="admission" value="${esc(s.admission||'')}" required></label><label>Roll No.<input name="roll" value="${esc(s.roll||'')}" required></label><label>Date of birth<input name="dob" type="date" value="${esc(s.dob||'')}" required></label><label>Gender<select name="gender"><option ${s.gender==='Male'?'selected':''}>Male</option><option ${s.gender==='Female'?'selected':''}>Female</option><option ${s.gender==='Other'?'selected':''}>Other</option></select></label><label>Class<select name="classId" id="classSel">${db.classes.map(c=>`<option value="${c.id}" ${s.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Section<select name="sectionId" id="secSel">${db.sections.map(x=>`<option value="${x.id}" data-class="${x.classId}" ${s.sectionId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Linked Parent<select name="parentId" id="parentSel"><option value="">+ Create / Link Parent</option>${parents.map(p=>`<option value="${p.id}" ${s.parentId===p.id?'selected':''}>${esc(p.name)} · ${esc(p.email||'No Gmail')}</option>`).join('')}</select></label><label>Parent Name<input name="parentName" value="${esc(linked.name||'')}" placeholder="Parent full name"></label><label>Parent Gmail<input name="parentEmail" type="email" value="${esc(linked.email||'')}" placeholder="parent@gmail.com"></label><label>Parent Password <small>(new parent / change if needed)</small><input name="parentPassword" type="password" placeholder="parent123"></label><label>Student password ${s.id?'(leave blank to keep current)':''}<input name="studentPassword" type="password" placeholder="student123"></label><div class="actions"><button class="btn primary">Save Student & Parent Link</button><a class="btn" href="/students">Cancel</a></div></form><script>const c=document.getElementById('classSel'),s=document.getElementById('secSel'),p=document.getElementById('parentSel');function f(){[...s.options].forEach(o=>o.hidden=o.dataset.class!==c.value);if(s.selectedOptions[0]?.hidden){const x=[...s.options].find(o=>!o.hidden);if(x)s.value=x.value}}c.onchange=f;f();p.onchange=()=>{const x=p.selectedOptions[0]?.textContent||'';};</script>`)}
function teacherForm(t={}){const u=t.userId?db.users.find(x=>x.id===t.userId):null;const ats=t.id?db.assignments.filter(x=>x.teacherId===t.id):[];const rows=Array.from({length:12},(_,i)=>ats[i]||{});return head(t.id?'Edit Teacher':'Add Teacher','Create teacher login and assign Session + Class + Section + Subject')+card(`<form method="post" action="${t.id?'/teachers/'+t.id:'/teachers'}" class="formgrid"><label>Full name<input name="name" value="${esc(u?.name||'')}" required></label><label>Login email<input name="email" type="email" value="${esc(u?.email||'')}" required></label><label>Password<input name="password" type="password" placeholder="${t.id?'Leave blank to keep current':'teacher123'}"></label><label>Employee ID<input name="employeeId" value="${esc(t.employeeId||'')}" required></label><label>Phone<input name="phone" value="${esc(t.phone||'')}"></label><h3>Academic Assignments</h3><div class="tablewrap"><table><thead><tr><th>Session</th><th>Class</th><th>Section</th><th>Subject</th></tr></thead><tbody>${rows.map((a,i)=>`<tr><td><select name="ay_${i}"><option value="">—</option>${db.years.map(y=>`<option value="${y.id}" ${a.yearId===y.id?'selected':''}>${esc(y.name)}</option>`).join('')}</select></td><td><select name="cl_${i}"><option value="">—</option>${db.classes.map(c=>`<option value="${c.id}" ${a.classId===c.id?'selected':''}>${esc(c.name)} · ${esc(db.years.find(y=>y.id===c.yearId)?.name||'')}</option>`).join('')}</select></td><td><select name="se_${i}"><option value="">—</option>${db.sections.map(x=>`<option value="${x.id}" ${a.sectionId===x.id?'selected':''}>${esc(x.name)} · ${esc(cls(x.classId)?.name||'')}</option>`).join('')}</select></td><td><input name="sub_${i}" value="${esc(a.subject||'')}" placeholder="Mathematics"></td></tr>`).join('')}</tbody></table></div><small class="muted">Teacher access is enforced by Session + Class + Section + Subject on the server.</small><div class="actions"><button class="btn primary">Save Teacher & Assignments</button><a class="btn" href="/teachers">Cancel</a></div></form>`)}
