function attendancePage(req,u){const y=currentYear(req,u),as=assignments(u,req);if(!as.length)return head('Attendance','No assignment')+card('<h2>No class assigned</h2><p>Ask the administrator to assign a class/section.</p>');const url=new URL(req.url,'http://localhost'),first=as[0],classId=url.searchParams.get('classId')||first.classId,secs=as.filter(a=>String(a.classId)===String(classId)),sectionId=url.searchParams.get('sectionId')||secs[0].sectionId,date=url.searchParams.get('date')||today(),students=db.students.filter(s=>String(s.classId)===String(classId)&&String(s.sectionId)===String(sectionId)&&s.active).sort((a,b)=>Number(a.roll)-Number(b.roll)),a=db.attendance.find(x=>x.date===date&&x.yearId===y.id&&String(x.classId)===String(classId)&&String(x.sectionId)===String(sectionId));return head('Mark Attendance','Select class, section and date',`<a class="btn" href="/reports">Reports</a>`)+card(`<form class="toolbar" method="get"><input type="hidden" name="yearId" value="${y.id}"><select name="classId" onchange="this.form.submit()">${[...new Map(as.map(x=>[x.classId,x.className]))].map(([i,n])=>`<option value="${i}" ${String(i)===String(classId)?'selected':''}>${esc(n)}</option>`).join('')}</select><select name="sectionId">${secs.map(x=>`<option value="${x.sectionId}" ${String(x.sectionId)===String(sectionId)?'selected':''}>${esc(x.sectionName)}</option>`).join('')}</select><input name="date" type="date" value="${date}"><button class="btn">Load</button></form><form method="post" action="/attendance/save"><input type="hidden" name="yearId" value="${y.id}"><input type="hidden" name="date" value="${date}"><input type="hidden" name="classId" value="${classId}"><input type="hidden" name="sectionId" value="${sectionId}"><div class="actions"><button type="button" class="btn" onclick="markAll('Present')">Mark All Present</button><button type="button" class="btn" onclick="markAll('Absent')">Mark All Absent</button><button class="btn primary">Save Attendance</button></div><div class="attlist">${students.map(s=>{const r=a?.records?.[s.id],st=r?.status||'Present';return `<div class="attrow"><b>${esc(s.roll)}</b><div>${avatar({name:s.name,avatar:s.photo},36)} <b>${esc(s.name)}</b><small>${esc(s.studentId)}</small></div><div class="status">${['Present','Absent','Late'].map(v=>`<label><input type="radio" name="status_${s.id}" value="${v}" ${st===v?'checked':''}><span>${v}</span></label>`).join('')}</div><input name="remark_${s.id}" placeholder="Remark" value="${esc(r?.remark||'')}"></div>`}).join('')}</div></form><script>function markAll(v){document.querySelectorAll('.attrow').forEach(r=>{const x=r.querySelector('input[value="'+v+'"]');if(x)x.checked=true})}</script>`)}
function reportsPage(req,u){const url=new URL(req.url,'http://localhost'),y=currentYear(req,u),from=url.searchParams.get('from')||y.start||today(),to=url.searchParams.get('to')||today(),as=new Set(assignments(u,req).map(x=>x.sectionId)),rows=flatAttendance(a=>a.yearId===y.id&&a.date>=from&&a.date<=to&&as.has(a.sectionId));const byStudent={};rows.forEach(r=>(byStudent[r.sid]??=[]).push(r));const summaries=Object.entries(byStudent).map(([sid,rs])=>({s:student(sid),total:rs.length,present:rs.filter(r=>r.status!=='Absent').length,absent:rs.filter(r=>r.status==='Absent').length,late:rs.filter(r=>r.status==='Late').length,pct:rs.length?Math.round(rs.filter(r=>r.status!=='Absent').length/rs.length*100):0}));return head('Reports','Daily, monthly and student-wise attendance reports',`<a class="btn" href="/reports.csv?yearId=${y.id}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}">↓ Export CSV</a>`)+card(`<form class="toolbar"><label>From<input name="from" type="date" value="${from}"></label><label>To<input name="to" type="date" value="${to}"></label><button class="btn primary">Generate</button></form><div class="stats-grid">${stat('Records',rows.length,'▤','blue')}${stat('Present/Late',rows.filter(x=>x.status!=='Absent').length,'✓','green')}${stat('Absent',rows.filter(x=>x.status==='Absent').length,'×','red')}${stat('Below 75%',summaries.filter(x=>x.pct<75).length,'⚠','orange')}</div><div class="tablewrap"><table><thead><tr><th>Student</th><th>Class</th><th>Total</th><th>Present/Late</th><th>Absent</th><th>Attendance %</th><th>Report Card</th></tr></thead><tbody>${summaries.map(x=>`<tr><td><b>${esc(x.s?.name)}</b><small>${esc(x.s?.studentId)}</small></td><td>${esc(cls(x.s?.classId)?.name||'')}</td><td>${x.total}</td><td>${x.present}</td><td>${x.absent}</td><td><span class="badge ${x.pct<75?'absent':'present'}">${x.pct}%</span></td><td><a class="btn small" href="/report-card?studentId=${x.s?.id}&yearId=${y.id}">Open</a></td></tr>`).join('')}</tbody></table></div>`)}
function assessmentPage(req,u){
 const url=new URL(req.url,'http://localhost'),requestedYear=url.searchParams.get('yearId'),selectedYear=db.years.find(y=>y.id===requestedYear)||activeYear(),as=assignments(u,{url:'/assessments?yearId='+encodeURIComponent(selectedYear.id)}),edit=url.searchParams.get('id'),existing=db.assessments.find(a=>a.id===edit&&a.yearId===selectedYear.id);
 if(edit&&!existing)return head('Test & Exam','Assessment not found in selected session')+card('<p>This assessment belongs to another academic session.</p>');
 const selected=existing||null;
 const visibleYears=u.role==='admin'?db.years:db.years.filter(y=>db.assignments.some(a=>a.teacherId===teacher(u)?.id&&a.yearId===y.id));
 const allowedPolicies=db.assessmentPolicies.filter(p=>p.roles.includes(u.role));
 const subjectSet=new Set(SUBJECTS);as.forEach(a=>{if(a.subject&&a.subject!=='All Subjects')subjectSet.add(a.subject)});db.assessments.filter(a=>a.yearId===selectedYear.id).forEach(a=>{if(a.subject&&a.subject!=='All Subjects')subjectSet.add(a.subject)});
 const subjectOptions=[...subjectSet].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
 const yearOptions=visibleYears.map(y=>`<option value="${y.id}" ${y.id===selectedYear.id?'selected':''}>${esc(y.name)}${y.active?' · Current':''}</option>`).join('');
 const classOptions=[...new Map(as.map(a=>[a.classId,a.className]))].map(([id,n])=>`<option value="${id}" ${selected?.classId===id?'selected':''}>${esc(n)}</option>`).join('');
 const assignmentRows=as.map(a=>`<span data-assignment data-class="${a.classId}" data-section="${a.sectionId}" data-subject="${esc(a.subject||'All Subjects')}"></span>`).join('');
 const form=card(`<h2>${selected?'Edit':'Add'} Assessment</h2><p class="muted">Choose the academic session, class, section and <b>specific subject</b>. Teacher access is limited to assignments created by Admin.</p><form method="post" action="/assessments/save" class="formgrid" id="assessmentForm"><input type="hidden" name="id" value="${selected?.id||''}">${assignmentRows}<label>Academic Session<select name="yearId" id="aySel" onchange="location.href='/assessments?yearId='+this.value">${yearOptions}</select></label><label>Type<select name="type">${allowedPolicies.map(p=>`<option ${selected?.type===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Title<input name="title" value="${esc(selected?.title||'Unit Test 1')}" required></label><label>Date<input name="date" type="date" value="${selected?.date||today()}" required></label><label>Class<select name="classId" id="aClass" required>${classOptions}</select></label><label>Section<select name="sectionId" id="aSection" required></select></label><label>Subject<select name="subject" id="aSubject" required>${subjectOptions}</select></label><label>Out of Marks<input name="maxMarks" type="number" min="1" value="${selected?.maxMarks||20}" required></label><div class="actions"><button class="btn primary">${selected?'Update':'Create'} Assessment</button><a class="btn" href="/assessments?yearId=${encodeURIComponent(selectedYear.id)}">Clear</a></div></form><script>
 const assigns=${JSON.stringify(as.map(a=>({classId:a.classId,sectionId:a.sectionId,sectionName:a.sectionName,subject:a.subject||'All Subjects'})))}, subSel=document.getElementById('aSubject'), secSel=document.getElementById('aSection'), classSel=document.getElementById('aClass');
 function refreshAssessmentFields(){const c=classSel.value;const rows=assigns.filter(a=>a.classId===c);const sections=[...new Map(rows.map(a=>[a.sectionId,a.sectionName]))];secSel.innerHTML=sections.map(([id,n])=>'<option value="'+id+'">'+n+'</option>').join('');${selected?`if(${JSON.stringify(selected.sectionId)})secSel.value=${JSON.stringify(selected.sectionId)};`:''} const sec=secSel.value;const subjects=[...new Set(rows.filter(a=>!sec||a.sectionId===sec).flatMap(a=>a.subject==='All Subjects'?${JSON.stringify(SUBJECTS)}:[a.subject]))];subSel.innerHTML=subjects.map(x=>'<option value="'+x+'">'+x+'</option>').join('');${selected?`if(${JSON.stringify(selected.subject)})subSel.value=${JSON.stringify(selected.subject)};`:''}}
 classSel.onchange=refreshAssessmentFields;secSel.onchange=refreshAssessmentFields;refreshAssessmentFields();
 </script>`);
 const list=db.assessments.filter(a=>a.yearId===selectedYear.id&&allowedClass(u,a.classId,a.sectionId,a.yearId,{url:'/assessments?yearId='+selectedYear.id})&&allowedSubject(u,a.classId,a.sectionId,a.subject,a.yearId,{url:'/assessments?yearId='+selectedYear.id})).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const p=policy(a.type);return `<tr><td><span class="badge ${p.external?'late':'present'}">${esc(a.type)}</span></td><td><b>${esc(a.title)}</b><small>${esc(a.subject)}</small></td><td>${esc(a.date)}</td><td>${esc(cls(a.classId)?.name||'')} / ${esc(sec(a.sectionId)?.name||'')}</td><td>${a.maxMarks}</td><td>${Object.keys(a.marks||{}).length}</td><td><a class="btn small" href="/assessments?id=${a.id}&yearId=${selectedYear.id}">Enter/Edit Marks</a></td></tr>`}).join('');
 let marksForm='';
 if(selected&&allowedClass(u,selected.classId,selected.sectionId,selected.yearId,{url:'/assessments?yearId='+selected.yearId})&&allowedSubject(u,selected.classId,selected.sectionId,selected.subject,selected.yearId,{url:'/assessments?yearId='+selected.yearId})){const students=db.students.filter(s=>s.classId===selected.classId&&s.sectionId===selected.sectionId&&s.active).sort((a,b)=>Number(a.roll)-Number(b.roll));marksForm=card(`<h2>Marks — ${esc(selected.title)}</h2><p class="muted">${esc(selectedYear.name)} · ${esc(cls(selected.classId)?.name||'')} / ${esc(sec(selected.sectionId)?.name||'')} · ${esc(selected.subject)}</p><form method="post" action="/assessments/marks"><input type="hidden" name="id" value="${selected.id}"><input type="hidden" name="yearId" value="${selected.yearId}"><div class="tablewrap"><table><thead><tr><th>Roll</th><th>Student ID</th><th>Student</th><th>Obtained / ${selected.maxMarks}</th></tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.roll)}</td><td>${esc(s.studentId)}</td><td>${esc(s.name)}</td><td><input name="mark_${s.id}" type="number" min="0" max="${selected.maxMarks}" value="${selected.marks?.[s.id]??''}" required></td></tr>`).join('')}</tbody></table></div><button class="btn primary">Save Marks</button></form>`)}
 return head('Test & Exam','Session-wise assessments with class + section + subject access control',`<span class="tag">Session ${esc(selectedYear.name)}</span>`)+form+marksForm+card('<div class="row-between"><h2>Assessment List</h2><span class="muted">Teacher: only Admin-assigned Session + Class + Section + Subject.</span></div><div class="tablewrap"><table><thead><tr><th>Type</th><th>Assessment / Subject</th><th>Date</th><th>Class / Section</th><th>Out of</th><th>Marks Entered</th><th>Action</th></tr></thead><tbody>'+list+'</tbody></table></div>')
}
function subjectSummary(ass,sid){const m={};ass.forEach(a=>{const sub=a.subject||'General';if(!m[sub])m[sub]={n:0,o:0,x:0};m[sub].n++;m[sub].o+=Number(a.marks?.[sid]||0);m[sub].x+=Number(a.maxMarks||0)});const rows=Object.entries(m).map(([sub,v])=>{const pc=v.x?Math.round(v.o/v.x*100):0;return `<tr><td><b>${esc(sub)}</b></td><td>${v.n}</td><td>${v.o}</td><td>${v.x}</td><td>${pc}%</td><td><b>${grade(pc)}</b></td></tr>`}).join('');return `<div class=\"tablewrap\"><table><thead><tr><th>Subject</th><th>Assessments</th><th>Obtained</th><th>Out of</th><th>Percentage</th><th>Grade</th></tr></thead><tbody>${rows||'<tr><td colspan=\"6\">No subject-wise marks entered yet.</td></tr>'}</tbody></table></div>`}
function reportCardPage(req,u){const q=new URL(req.url,'http://localhost').searchParams;let sid=q.get('studentId');let visibleStudents=[];if(u.role==='admin')visibleStudents=db.students.filter(s=>s.active);else if(u.role==='teacher')visibleStudents=db.students.filter(x=>x.active&&assignments(u,req).some(a=>a.classId===x.classId&&a.sectionId===x.sectionId&&a.yearId===currentYear(req,u).id));else if(u.role==='student'){const own=student(u.studentId);visibleStudents=own?[own]:[];sid=own?.id||sid}else if(u.role==='parent'){const pid=parent(u)?.id;visibleStudents=db.students.filter(x=>x.active&&x.parentId===pid);if(!sid||!visibleStudents.some(x=>x.id===sid))sid=visibleStudents[0]?.id}if(!sid)sid=visibleStudents[0]?.id; if(!visibleStudents.some(x=>x.id===sid))sid=visibleStudents[0]?.id;const s=student(sid);if(!s)return head('Annual Report Card','No linked student available')+card('<p>No student is available for this account.</p>');const pu=db.users.find(x=>x.studentId===s.id),yearId=currentYear(req,u).id,rows=flatAttendance((a,x)=>x.id===s.id&&a.yearId===yearId),present=rows.filter(r=>r.status!=='Absent').length,pct=rows.length?Math.round(present/rows.length*100):0,ass=db.assessments.filter(a=>a.yearId===yearId&&a.classId===s.classId&&a.sectionId===s.sectionId&&policy(a.type).internal&&a.marks&&Object.prototype.hasOwnProperty.call(a.marks,s.id)).sort((a,b)=>a.date.localeCompare(b.date));const totalObt=ass.reduce((n,a)=>n+Number(a.marks[s.id]||0),0),totalMax=ass.reduce((n,a)=>n+Number(a.maxMarks||0),0),overall=totalMax?Math.round(totalObt/totalMax*100):0;const studentPicker=visibleStudents.length>1?`<form class="toolbar"><input type="hidden" name="yearId" value="${yearId}"><label>Student<select name="studentId" onchange="this.form.submit()">${visibleStudents.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.studentId)} · ${esc(x.name)}</option>`).join('')}</select></label></form>`:'';const sig=db.school.principalSignature?`<div class="principal-sign"><img src="${esc(db.school.principalSignature)}" alt="Principal Signature"><b>${esc(db.school.principalName||'Principal')}</b><span>Principal</span></div>`:`<div class="principal-sign"><b>${esc(db.school.principalName||'Principal')}</b><span>Principal Signature</span></div>`;return head('Annual Report Card','Attendance + Tests + Exams + overall annual performance',`<button class="btn primary" onclick="window.print()">🖨 Generate / Print Report Card</button>`)+studentPicker+`<section class="report-card">${hero()}<div class="report-head"><div>${avatar(pu||{name:s.name,avatar:s.photo},90)}</div><div><h1>ANNUAL REPORT CARD</h1><h2>${esc(s.name)}</h2><p>Student ID: <b>${esc(s.studentId)}</b> · Admission No: ${esc(s.admission)} · Roll No: ${esc(s.roll)}</p><p>${esc(cls(s.classId)?.name||'')} · Section ${esc(sec(s.sectionId)?.name||'')} · Academic Year ${esc(currentYear(req,u).name)}</p></div><div class="report-result"><b>${grade(overall)}</b><span>${overall}%</span><small>Overall</small></div></div><div class="report-stats"><div><b>${pct}%</b><span>Attendance</span></div><div><b>${rows.filter(r=>r.status==='Present').length}</b><span>Present</span></div><div><b>${rows.filter(r=>r.status==='Absent').length}</b><span>Absent</span></div><div><b>${totalObt}/${totalMax}</b><span>Total Marks</span></div></div><h3>Test & Examination Performance</h3><div class="tablewrap"><table><thead><tr><th>Type</th><th>Assessment</th><th>Date</th><th>Subject</th><th>Obtained</th><th>Out of</th><th>Percentage</th><th>Grade</th></tr></thead><tbody>${ass.length?ass.map(a=>{const ob=Number(a.marks[s.id]||0),pc=a.maxMarks?Math.round(ob/a.maxMarks*100):0;return `<tr><td>${esc(a.type)}</td><td><b>${esc(a.title)}</b></td><td>${esc(a.date)}</td><td>${esc(a.subject)}</td><td>${ob}</td><td>${a.maxMarks}</td><td>${pc}%</td><td><b>${grade(pc)}</b></td></tr>`}).join(''):'<tr><td colspan="8">No Tests or Exams entered yet.</td></tr>'}</tbody></table></div><h3>Subject-wise Summary</h3>${subjectSummary(ass,s.id)}<div class="report-footer"><div><b>Attendance Status</b><p>${pct>=75?'Eligible — attendance meets the 75% requirement.':'Warning — attendance is below the 75% requirement.'}</p></div><div><b>Annual Result</b><p>${totalMax?`Overall ${overall}% · Grade ${grade(overall)}`:'Marks pending'}</p></div>${sig}</div></section><style>.principal-sign{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;min-width:180px;min-height:100px;text-align:center}.principal-sign img{max-width:180px;max-height:70px;object-fit:contain;margin-bottom:4px}.principal-sign span{font-size:12px;color:#666}@media print{aside,header,.pagehead,.toolbar{display:none!important}main{width:100%}.report-card{box-shadow:none!important;border:0!important;margin:0!important}.report-card .hero{display:flex!important}}</style>`}

function profilePage(req,u,msg=''){return head('My Profile','Manage your profile, password and profile picture')+card(`<div class="profile-large">${avatar(u,96)}<div><h2>${esc(u.name)}</h2><p>${esc(u.role)} · ${esc(u.role==='student'?'Student ID: '+(student(u.studentId)?.studentId||''):u.email)}</p></div></div>${msg?'<div class="success">'+esc(msg)+'</div>':''}<form method="post" action="/profile" class="formgrid"><label>Full name<input name="name" value="${esc(u.name)}" required></label><label>Email<input name="email" value="${esc(u.email)}" ${u.role==='student'?'readonly':''}></label><label>Profile Picture<input type="file" id="photoFile" accept="image/*"><input type="hidden" name="avatar" id="avatarData"><small class="muted">Choose a photo; it will be saved with your profile.</small></label><label>New Password<input name="password" type="password" placeholder="Leave blank to keep current"></label><div class="actions"><button class="btn primary">Save Profile</button></div></form><script>document.getElementById('photoFile').onchange=function(){const f=this.files[0];if(!f)return;const r=new FileReader();r.onload=()=>document.getElementById('avatarData').value=r.result;r.readAsDataURL(f)}</script>`)}
function usersPage(){return head('User Accounts','Login accounts for administrators, teachers, students and parents',`<a class="btn primary" href="/users/new">＋ Add Account</a>`)+card('<div class="tablewrap"><table><thead><tr><th>Name</th><th>Login</th><th>Role</th><th>Status</th></tr></thead><tbody>'+db.users.map(x=>`<tr><td>${avatar(x,30)} ${esc(x.name)}</td><td>${esc(x.role==='student'?(student(x.studentId)?.studentId||'—'):x.email)}</td><td>${esc(x.role)}</td><td>${x.active?'Active':'Disabled'}</td></tr>`).join('')+'</tbody></table></div>')}
function userForm(){return head('Add User Account','Create a login account')+card(`<form method="post" action="/users" class="formgrid"><label>Role<select name="role"><option>student</option><option>parent</option><option>teacher</option><option>admin</option></select></label><label>Full name<input name="name" required></label><label>Login email (not required for Student)<input name="email" type="email"></label><label>Password<input name="password" type="password" required></label><label>Link student<select name="studentId"><option value="">None</option>${db.students.filter(s=>!db.users.some(x=>x.studentId===s.id)).map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.studentId)}</option>`).join('')}</select></label><div><button class="btn primary">Create Account</button></div></form>`)}
function sessionsPage(){return head('Academic Sessions','Admin-only session management. Create, edit and set the current session.',`<a class="btn primary" href="/academic-sessions/new">＋ New Session</a>`)+card(`<div class="tablewrap"><table><thead><tr><th>Session</th><th>Start</th><th>End</th><th>Status</th><th>Action</th></tr></thead><tbody>${db.years.map(y=>`<tr><td><b>${esc(y.name)}</b></td><td>${esc(y.start)}</td><td>${esc(y.end)}</td><td>${y.active?'<span class="badge present">Current</span>':'<span class="badge">Archived</span>'}</td><td><a class="btn small" href="/academic-sessions/${y.id}/edit">Edit</a>${!y.active?`<form method="post" action="/academic-sessions/${y.id}/activate" style="display:inline"><button class="btn small">Set Current</button></form>`:''}</td></tr>`).join('')}</tbody></table></div>`)}
function sessionForm(y={}){return head(y.id?'Edit Academic Session':'New Academic Session','Only Admin can create, edit or activate academic sessions.')+card(`<form method="post" action="${y.id?'/academic-sessions/'+y.id:'/academic-sessions'}" class="formgrid"><label>Session Name<input name="name" value="${esc(y.name||'')}" placeholder="2027-28" required></label><label>Start Date<input name="start" type="date" value="${esc(y.start||'')}" required></label><label>End Date<input name="end" type="date" value="${esc(y.end||'')}" required></label><label><input type="checkbox" name="active" ${y.active?'checked':''}> Make this the current session</label><div class="actions"><button class="btn primary">Save Session</button><a class="btn" href="/academic-sessions">Cancel</a></div></form>`)}
function settingsPage(){const sig=db.school.principalSignature||'';return head('Settings','School application settings')+card(`<h2>Assessment Entry Permissions</h2><p>Admin controls who can enter each assessment type. Board Exam is external and excluded from internal report cards.</p><form method="post" action="/assessment-policies" class="formgrid">${db.assessmentPolicies.map((p,i)=>`<label><b>${esc(p.name)}</b> <small>${p.external?'External / Board':'Internal'}</small><div><label><input type="checkbox" name="adm_${i}" ${p.roles.includes('admin')?'checked':''}> Admin</label> <label><input type="checkbox" name="tea_${i}" ${p.roles.includes('teacher')?'checked':''}> Teacher</label></div></label>`).join('')}<label>Add custom assessment type<input name="newType" placeholder="e.g. Pre-Final"></label><div class="actions"><button class="btn primary">Save Assessment Permissions</button></div></form><h2>Attendance rule</h2><p>Students below <b>75%</b> are flagged.</p><h2>School branding</h2><p>Ajeet Public School logo and campus image are used across the portal.</p><h2>Principal / Report Card</h2><form method="post" action="/settings" class="formgrid" onsubmit="return prepareSig()"><label>Principal Name<input name="principalName" value="${esc(db.school.principalName||'')}" required></label><label>Principal Signature<input id="sigFile" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="principalSignature" id="sigData" value="${esc(sig)}"><small>Upload a scanned signature image. It will appear on generated/printed report cards.</small></label><div>${sig?`<img src="${esc(sig)}" style="max-width:220px;max-height:90px;object-fit:contain;border:1px solid #ddd;padding:8px;border-radius:8px" alt="Principal signature">`:'<p>No signature uploaded yet.</p>'}</div><div><button class="btn primary">Save Principal Details</button></div></form><h2>Data storage</h2><p>Local school server data is stored in <code>school-data.json</code>. Back it up regularly.</p><script>function prepareSig(){const f=document.getElementById('sigFile');if(f.files&&f.files[0]){const r=new FileReader();r.onload=()=>{document.getElementById('sigData').value=r.result;document.querySelector('form[action="/settings"]').submit()};r.readAsDataURL(f.files[0]);return false}return true}</script>`)}
